/* Product: navigation, centered copy, a live product window under it, and customers at the bottom. The page is one solid
   color with a faint dot grid; the accent appears only as solid fills (marker, primary button, active tab) and thin strokes. */
.hero { display: flex; flex-direction: column; }
.dots { --dots-fade: linear-gradient(to bottom, #000 0%, #000 52%, transparent 88%); }

.copy { position: relative; display: grid; box-sizing: border-box; width: 100%; max-width: 920px; justify-items: center; gap: var(--space-4); margin: 0 auto; padding: clamp(24px, 2.6cqi, 34px) var(--space-10) 0; text-align: center; }

.eyebrow { display: inline-flex; height: 30px; align-items: center; gap: 8px; margin: 0; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 0 12px 0 4px; background: var(--surface); color: var(--text-secondary); font-size: var(--text-sm); white-space: nowrap; }
.tag { display: inline-flex; height: 22px; align-items: center; border-radius: var(--radius-pill); padding: 0 9px; background: var(--accent); color: var(--accent-foreground); font-size: var(--text-xs); font-weight: 600; }

.title { margin-top: var(--space-1); font-size: clamp(2.5rem, 1rem + 4.4cqi, 4rem); line-height: 1.06; }
.description { max-width: 620px; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3); margin-top: var(--space-2); }

/* Social proof: five faces, a rating, and how many teams. */
.proof { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--space-2) var(--space-4); color: var(--text-secondary); font-size: var(--text-sm); }
.faces { display: inline-flex; padding-left: 7px; }
.faces .face { width: 30px; height: 30px; margin-left: -7px; border: 2px solid var(--background); background: color-mix(in oklab, var(--face) 24%, var(--surface)); color: color-mix(in oklab, var(--face) 72%, var(--foreground)); font-size: 10px; font-weight: 600; letter-spacing: 0; }
.rating { display: inline-flex; align-items: center; gap: 6px; }
.rating strong { color: var(--foreground); font-weight: 600; font-variant-numeric: tabular-nums; }
.stars { display: inline-flex; gap: 1px; color: var(--series-1); }
.proofText { border-left: 1px solid var(--border); padding-left: var(--space-4); }

/* Stage: the window, with room at both sides for the cards that float over its edges. --over is how far a card may hang
   outside the window before it would leave the page. */
.stage { position: relative; box-sizing: border-box; width: 100%; max-width: calc(1000px + 2 * var(--space-10)); margin: var(--space-10) auto 0; padding: 0 var(--space-10); }
.frame { --over: clamp(16px, calc((100cqi - 1000px) / 2 - 20px), 104px); position: relative; }

.window { position: relative; overflow: hidden; border: 1px solid var(--border); border-radius: 18px; background: var(--surface); box-shadow: var(--shadow-floating); color: var(--foreground); font-size: 13px; line-height: 1.35; text-align: left; }
.chrome { display: grid; height: 40px; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid var(--border-subtle); padding: 0 14px; }
.lights { display: flex; gap: 6px; }
.lights i { width: 10px; height: 10px; border-radius: 50%; background: var(--border-strong); }
.url { display: inline-flex; height: 24px; align-items: center; gap: 6px; border-radius: 8px; padding: 0 12px; background: var(--surface-muted); color: var(--text-muted); font-size: 12px; }

.app { display: grid; grid-template-columns: 56px minmax(0, 1fr); }
.side { display: flex; flex-direction: column; align-items: center; gap: 6px; border-right: 1px solid var(--border-subtle); padding: 14px 0; }
.sideItem { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 10px; color: var(--text-muted); }
.sideItem[data-active] { background: var(--accent); color: var(--accent-foreground); }
.sideEnd { margin-top: auto; }

.main { display: grid; align-content: start; gap: 14px; min-width: 0; padding: 18px 20px 20px; }
.head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.h2 { margin: 0; font-family: var(--font-display); font-size: 17px; font-weight: 600; letter-spacing: -.02em; line-height: 1.2; }
.sub { display: flex; align-items: center; gap: 6px; margin: 2px 0 0; color: var(--text-muted); font-size: 12px; }
.liveDot { width: 6px; height: 6px; flex: none; border-radius: 50%; background: var(--success); }
/* The range control is the ryan-ui segmented control at the window's smaller scale. */
.range { flex: none; }
.range :global(button) { min-height: 28px; padding: 0 11px; font-size: 12px; }

.card { box-sizing: border-box; min-width: 0; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-raised); }
.cardHead { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.cardTitle { margin: 0; font-size: 13px; font-weight: 600; line-height: 1.35; }
.cardNote { margin: 1px 0 0; color: var(--text-muted); font-size: 12px; }

.kpis { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.kpi { display: grid; gap: 9px; padding: 13px 16px 14px; }
.kpiTop { display: flex; align-items: center; justify-content: space-between; gap: 8px; color: var(--text-secondary); }
.kpiTop svg { flex: none; color: var(--text-muted); }
.kpiValue { display: flex; height: 30px; align-items: center; font-family: var(--font-display); font-size: 26px; font-weight: 500; letter-spacing: -.03em; line-height: 1; font-variant-numeric: tabular-nums; }
/* The counter is the ryan-ui animated counter; it takes the card's type size. */
.kpiValue > span { font-size: inherit; letter-spacing: inherit; }
.kpiGhost { visibility: hidden; }
.kpiFoot { display: flex; min-width: 0; align-items: center; gap: 8px; overflow: hidden; color: var(--text-muted); font-size: 12px; white-space: nowrap; }
.against { overflow: hidden; text-overflow: ellipsis; }

.grid { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 12px; }
.chartCard { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 14px 16px 12px; }
.legend { display: flex; flex: none; gap: 14px; color: var(--text-muted); font-size: 12px; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 14px; height: 0; border-top: 2px solid var(--series-1); border-radius: 2px; }
.swatch[data-previous] { border-top: 2px dotted var(--border-strong); border-radius: 0; }

/* The plot: a value axis, the drawing area, and a date axis under it. The line is drawn in a 100 by 100 box stretched over the
   area, with strokes that keep their width; the end point is an element, so it stays round. */
.plot { display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-rows: var(--plot-height, 172px) auto; gap: 8px 10px; }
.yAxis { position: relative; grid-area: 1 / 1; width: 32px; color: var(--text-muted); font-size: 11px; font-variant-numeric: tabular-nums; }
.yAxis span { position: absolute; right: 0; line-height: 1; transform: translateY(-50%); }
.canvas { position: relative; grid-area: 1 / 2; margin-right: 8px; }
.gridline { position: absolute; right: 0; left: 0; height: 0; border-top: 1px dashed var(--border); }
.gridline[data-base] { border-top-style: solid; }
.svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.line { fill: none; stroke: var(--series-1); stroke-width: 2.25; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.previous { fill: none; stroke: var(--border-strong); stroke-width: 1.5; stroke-dasharray: 2 5; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.area { fill: color-mix(in oklab, var(--series-1) 10%, transparent); }
.end { position: absolute; right: -5px; width: 10px; height: 10px; margin-top: -5px; border-radius: 50%; background: var(--series-1); box-shadow: 0 0 0 3px var(--surface-raised); opacity: 0; scale: .4; transition: opacity var(--duration-fast) var(--ease-standard), scale var(--duration-standard) var(--ease-spring); }
.end[data-on] { opacity: 1; scale: 1; }
.end::after { content: ""; position: absolute; z-index: -1; inset: 0; border-radius: 50%; background: var(--series-1); opacity: 0; }
.end[data-on]::after { animation: ping 1.9s var(--ease-standard) infinite; }
@keyframes ping { from { opacity: .5; transform: scale(1); } to { opacity: 0; transform: scale(3.6); } }
.xAxis { display: flex; grid-area: 2 / 2; justify-content: space-between; margin-right: 8px; color: var(--text-muted); font-size: 11px; font-variant-numeric: tabular-nums; line-height: 1.2; }

.tableCard { display: grid; align-content: start; gap: 8px; padding: 14px 16px 6px; }
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { border-top: 1px solid var(--border-subtle); padding: 9px 0; font-weight: 400; text-align: left; vertical-align: middle; }
.who { display: flex; min-width: 0; align-items: center; gap: 10px; }
.whoMark { display: grid; width: 28px; height: 28px; flex: none; place-items: center; border-radius: 9px; background: color-mix(in oklab, var(--face) 20%, var(--surface-raised)); color: color-mix(in oklab, var(--face) 74%, var(--foreground)); font-size: 12px; font-weight: 600; }
.whoText { display: grid; min-width: 0; line-height: 1.3; }
.whoText strong { overflow: hidden; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.whoText small { overflow: hidden; color: var(--text-muted); font-size: 11.5px; text-overflow: ellipsis; white-space: nowrap; }
.table .amount { padding-inline: 10px 14px; font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.table .status { width: 1%; text-align: right; white-space: nowrap; }

/* Floating cards. The slot places and enters the card; the inner wrapper bobs it, so the two transforms never meet. */
.float { position: absolute; z-index: 3; pointer-events: none; }
.toastSlot { top: -22px; right: calc(var(--over) * -.5); }
.goalSlot { top: 204px; left: calc(var(--over) * -1); }
.bob { animation: bob 5.6s var(--ease-in-out) infinite alternate; }
.goalSlot .bob { animation-duration: 6.8s; animation-delay: -2.4s; }
@keyframes bob { from { transform: translateY(-5px); } to { transform: translateY(5px); } }
.toast, .goal { display: flex; box-sizing: border-box; align-items: center; border: 1px solid var(--border); border-radius: 16px; background: var(--surface-raised); box-shadow: var(--shadow-floating); color: var(--foreground); font-size: 13px; text-align: left; }
.toast { width: 236px; gap: 10px; padding: 10px 14px 10px 10px; }
.goal { width: 172px; gap: 12px; padding: 10px 12px 10px 10px; }
.toastIcon { display: grid; width: 32px; height: 32px; flex: none; place-items: center; border-radius: 50%; background: var(--accent); color: var(--accent-foreground); }
.floatText { display: grid; flex: 1; min-width: 0; line-height: 1.3; }
.floatText strong { font-weight: 600; white-space: nowrap; }
.floatText small, .toastLine { color: var(--text-secondary); font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.toastLine { position: relative; display: block; height: 1.3em; overflow: hidden; }
.toastSwap { display: block; }
.ring { position: relative; display: grid; width: 44px; height: 44px; flex: none; }
.ring svg { transform: rotate(-90deg); }
.ringTrack, .ringValue { fill: none; stroke-width: 4; }
.ringTrack { stroke: var(--border); }
.ringValue { stroke: var(--series-1); stroke-linecap: round; }
.ringLabel { position: absolute; inset: 0; display: grid; place-items: center; font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums; }

/* Customers: invented names as grey wordmarks. */
.customers { display: grid; box-sizing: border-box; width: 100%; max-width: 1080px; justify-items: center; gap: var(--space-6); margin: 0 auto; padding: var(--space-16) var(--space-10) var(--space-12); text-align: center; }
.customers p { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }
.customers ul { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-4) var(--space-10); margin: 0; padding: 0; list-style: none; }
.customers li { display: inline-flex; align-items: center; gap: 8px; color: var(--text-muted); font-family: var(--font-display); font-size: var(--text-xl); font-weight: 600; letter-spacing: -.03em; white-space: nowrap; }

/* Without wide margins the goal card moves to the window's bottom corner, where it covers nothing that is read. */
@container hero (max-width: 1239px) {
  .toastSlot { right: -18px; }
  .goalSlot { top: auto; bottom: -42px; left: -18px; }
}
@container hero (max-width: 900px) {
  .grid { grid-template-columns: minmax(0, 1fr); }
  .against { display: none; }
}
@container hero (max-width: 760px) {
  .break { display: none; }
  .copy, .stage { padding-inline: var(--space-4); }
  .customers { padding: var(--space-16) var(--space-4) var(--space-10); }
  .app { grid-template-columns: minmax(0, 1fr); }
  .side, .legend, .url { display: none; }
  .toastSlot { right: -6px; }
  .goalSlot { bottom: -48px; left: -6px; }
}
@container hero (max-width: 560px) {
  .copy { gap: var(--space-4); }
  .actions { width: 100%; }
  .actions > * { flex: 1 1 auto; }
  .proofText { border-left: 0; padding-left: 0; }
  .stage { margin-top: var(--space-10); }
  .window { border-radius: 16px; }
  .chrome { height: 32px; }
  .main { gap: 10px; padding: 14px 12px 12px; }
  .kpis, .grid { gap: 8px; }
  .kpi { gap: 7px; padding: 10px 10px 11px; }
  .kpiTop svg { display: none; }
  .kpiValue { height: 24px; font-size: 19px; }
  .chartCard { padding: 12px 12px 10px; }
  .plot { --plot-height: 140px; }
  .tableCard { padding: 12px 12px 4px; }
  .whoText small { display: none; }
  .customers ul { display: grid; grid-template-columns: repeat(2, auto); justify-content: center; gap: var(--space-4) var(--space-8); }
  .customers li { font-size: var(--text-lg); }
}

@media (prefers-reduced-motion: reduce) {
  .bob, .end[data-on]::after { animation: none; }
  .end { transition: none; }
}

