/* Workflow, one full screen: the copy beside an editor panel. The panel is a toolbar, a dotted board with the automation graph,
   and the run summary. Lines and running states take the accent as a stroke (--hero-ink); nothing is a gradient. */
.hero { --wire: color-mix(in oklab, var(--foreground) 20%, transparent); display: flex; flex-direction: column; }

.inner { display: grid; flex: 1; box-sizing: border-box; width: 100%; max-width: 1240px; grid-template-columns: minmax(0, .88fr) minmax(0, 1fr); align-items: center; gap: var(--space-16); margin: 0 auto; padding: var(--space-8) var(--space-10) var(--space-16); }

.copy { display: grid; justify-items: start; gap: var(--space-5); text-align: left; }
.eyebrow { display: inline-flex; min-height: 30px; box-sizing: border-box; align-items: center; gap: 8px; margin: 0; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 4px 12px; background: var(--surface); color: var(--text-secondary); font-size: var(--text-sm); }
.title { font-size: clamp(2.5rem, 1.2rem + 4.2cqi, 4.25rem); line-height: 1.06; }
.description { max-width: 500px; }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-2); }
.fine { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }

/* The editor panel. */
.panel { min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: 20px; background: var(--surface); box-shadow: var(--shadow-raised); }
.toolbar { display: flex; height: 54px; box-sizing: border-box; align-items: center; justify-content: space-between; gap: var(--space-3); border-bottom: 1px solid var(--border); padding: 0 10px 0 16px; }
.file { display: inline-flex; min-width: 0; align-items: center; gap: 8px; color: var(--text-secondary); font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, monospace); font-size: 13px; }
.live { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--text-muted); transition: background-color var(--duration-standard) var(--ease-standard); }
.live[data-on] { background: var(--success); }

.board { position: relative; isolation: isolate; padding: 28px 24px; background: var(--background); }
.boardDots { --dots-fade: none; }
.stage { position: relative; width: 100%; max-width: 640px; margin: 0 auto; }
.graph { position: absolute; top: 0; left: 50%; translate: -50% 0; transform-origin: 50% 0; }
.edges { position: absolute; inset: 0; overflow: visible; }
.wire { fill: none; stroke: var(--wire); stroke-width: 1.5; }
.wire[data-skipped] { stroke-dasharray: 3 5; opacity: .7; }
.flow { fill: none; stroke: var(--hero-ink); stroke-width: 1.75; stroke-linecap: round; }
.pulse { fill: none; stroke: var(--hero-ink); stroke-width: 4.5; stroke-linecap: round; }

/* A node: what the step is, what it found, and its state. The running step takes the accent as its border. */
.node {
  position: absolute; display: flex; box-sizing: border-box; align-items: center; gap: 12px;
  border: 1px solid var(--border); border-radius: 16px; padding: 0 14px 0 12px;
  background: var(--surface); box-shadow: var(--shadow-resting);
  font-size: 13px; line-height: 1.3;
  transition: border-color var(--duration-standard) var(--ease-standard), opacity var(--duration-standard) var(--ease-standard), background-color var(--duration-standard) var(--ease-standard);
}
.node[data-status="running"] { border-color: var(--hero-ink); background: color-mix(in oklab, var(--accent) 6%, var(--surface)); }
.node[data-status="skipped"] { opacity: .5; box-shadow: none; }
.icon { display: grid; width: 32px; height: 32px; flex: none; place-items: center; border-radius: 10px; background: var(--surface-muted); color: var(--text-secondary); }
.icon[data-tone="accent"] { background: var(--accent); color: var(--accent-foreground); }
.text { display: grid; flex: 1; min-width: 0; }
.text strong { overflow: hidden; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.text small { overflow: hidden; color: var(--text-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }
.state { display: grid; flex: none; justify-items: end; }
.stateInner { display: inline-flex; align-items: center; gap: 6px; }
.meta { color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.check { color: var(--success); }
.skip { color: var(--text-muted); }
.pending { display: block; width: 10px; height: 10px; box-sizing: border-box; border: 1.5px solid var(--wire); border-radius: 50%; }
.spinner { display: block; width: 13px; height: 13px; flex: none; box-sizing: border-box; border: 1.5px solid color-mix(in oklab, var(--hero-ink) 24%, transparent); border-top-color: var(--hero-ink); border-radius: 50%; animation: spin .7s linear infinite; }
@keyframes spin { to { rotate: 360deg; } }

/* Action nodes: icon and state on top, the name and its result under them. */
.node[data-compact] { display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto auto; align-content: center; gap: 8px 4px; padding: 0 14px; }
.node[data-compact] .icon { width: 28px; height: 28px; border-radius: 9px; }
.node[data-compact] .text { grid-column: 1 / -1; }
.node[data-compact] .state { grid-column: 2; grid-row: 1; align-self: center; }

/* The run summary under the board. */
.summary { display: flex; min-height: 48px; box-sizing: border-box; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 12px; border-top: 1px solid var(--border); padding: 8px 16px; color: var(--text-muted); font-size: 13px; }
.event { display: inline-flex; align-items: center; gap: 12px; }
.event code { border: 1px solid var(--border); border-radius: 7px; padding: 1px 7px; background: var(--surface-raised); color: var(--text-secondary); font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, monospace); font-size: var(--text-xs); }
.num { font-variant-numeric: tabular-nums; }
.result { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }
.result[data-done] { color: var(--foreground); }
.result[data-done] svg { color: var(--success); }

@container hero (max-width: 960px) {
  .inner { grid-template-columns: minmax(0, 1fr); gap: var(--space-10); padding-top: var(--space-10); }
}
@container hero (max-width: 760px) {
  .break { display: none; }
  .inner { padding-inline: var(--space-4); }
}
@container hero (max-width: 560px) {
  .inner { gap: var(--space-8); padding: var(--space-6) var(--space-4) var(--space-8); }
  .copy { gap: var(--space-4); }
  .actions { width: 100%; margin-top: var(--space-1); }
  .actions > * { flex: 1 1 auto; }
  .panel { border-radius: 18px; }
  .board { padding: 18px 6px; }
  .node { border-radius: 14px; }
  .node[data-compact] { gap: 6px 4px; padding: 0 10px; }
  .node[data-compact] .icon { width: 26px; height: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  .spinner { animation: none; }
  .node, .live { transition: none; }
}

